/// <summary>
/// PaffH 05.02.22
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <param name = "_update">boolean</param>
/// <returns>NDXPAWithLabelInfo</returns>
public static NDXPAWithLabelInfo find(
    ProdId _prodId,
    boolean     _update = false)
{
    NDXPAWithLabelInfo  nDXPAWithLabelInfo;

    nDXPAWithLabelInfo.selectForUpdate(_update);

    select firstonly nDXPAWithLabelInfo
        where nDXPAWithLabelInfo.ProdId == _prodId;

    return nDXPAWithLabelInfo;
}

/// <summary>
/// PaffH 05.02.22
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <returns>NDXPAWithLabelInfo</returns>
public static NDXPAWithLabelInfo findOrCreate(ProdId  _prodId)
{
    NDXPAWithLabelInfo  nDXPAWithLabelInfo = NDXPAWithLabelInfo::find(_prodId, true);
    if (!nDXPAWithLabelInfo)
    {
        nDXPAWithLabelInfo.ProdId = _prodId;
        nDXPAWithLabelInfo.insert();
    }
    return nDXPAWithLabelInfo;
}

/// <summary>
/// PaffH 04.04.22
/// </summary>
/// <param name = "contractResponse">ResponseLabelSaved2DatabaseContract</param>
public static void Respond2ReturnContract(Niedax.AzureServiceBus.Models.PALabel.ResponseLabelSaved2DatabaseContract contractResponse)
{
    NDXPAWithLabelInfo nDXPAWithLabelInfo;
    nDXPAWithLabelInfo = NDXPAWithLabelInfo::find(contractResponse.NDXProdStatusChangedGenerateTransportLabelEventContract.ProdId);
    if (nDXPAWithLabelInfo)
    {
        if (Debug::debugMode())
        {
            Debug::printDebug(int642Str(nDXPAWithLabelInfo.BatchHeaderRefRecId));
        }
    }
}

/// <summary>
/// PaffH 15.05.23
/// </summary>
/// <param name = "_responseLabelSaved2DatabaseContract">ResponseLabelSaved2DatabaseContract</param>
public static void processFromResponseLabelSaved2DatabaseContract(Niedax.AzureServiceBus.Models.PALabel.ResponseLabelSaved2DatabaseContract _responseLabelSaved2DatabaseContract)
{
    NDXPAWithLabelInfo nDXPAWithLabelInfo = NDXPAWithLabelInfo::find(_responseLabelSaved2DatabaseContract.NDXProdStatusChangedGenerateTransportLabelEventContract.ProdId, true);
    if (nDXPAWithLabelInfo)
    {
        info(strFmt("@NDX:NDXProductionOrderWithLabelSavedAt", NDXHelperCommon::seconds2Str()
            ,_responseLabelSaved2DatabaseContract.NDXProdStatusChangedGenerateTransportLabelEventContract.ProdId
            ,DateTimeUtil::toStr(_responseLabelSaved2DatabaseContract.DtSaved2Database)));
        ttsbegin;
        nDXPAWithLabelInfo.ReceivedFromQueue = _responseLabelSaved2DatabaseContract.DtSaved2Database;
        nDXPAWithLabelInfo.update();
        ttscommit;
    }
}
